import { PrinterIcon } from 'lucide-react';
import type { ReactNode } from 'react';
import { Button } from '@/components/ui/button';

export type Letterhead = {
    legalName: string;
    lines: string[];
    logo?: ReactNode;
};

export type PrintMeta = { label: string; value: string };

export type PrintSheetLabels = { print: string; hint: string };

export const printSheetLabels: PrintSheetLabels = {
    print: 'Print',
    hint: 'Print from Chrome or Edge to get page numbers. Keep the default margins.',
};

export function PrintSheet({
    letterhead,
    title,
    number,
    meta = [],
    stamp = null,
    footer,
    onPrint = () => window.print(),
    labels = printSheetLabels,
    children,
}: {
    letterhead: Letterhead;
    title: string;
    number: string;
    meta?: PrintMeta[];
    stamp?: string | null;
    footer: string[];
    onPrint?: () => void;
    labels?: PrintSheetLabels;
    children: ReactNode;
}) {
    return (
        <div className="min-h-svh bg-slate-200/70 py-8 print:bg-white print:py-0">
            <div className="mx-auto mb-4 flex max-w-[210mm] items-center justify-between gap-4 px-4 print:hidden">
                <p className="text-xs text-muted-foreground">{labels.hint}</p>
                <Button onClick={onPrint}>
                    <PrinterIcon /> {labels.print}
                </Button>
            </div>
            <article className="relative mx-auto min-h-[297mm] max-w-[210mm] overflow-hidden bg-white px-[16mm] py-[18mm] text-[10.5pt] leading-[1.45] text-black shadow-lg print:min-h-0 print:max-w-none print:p-0 print:shadow-none">
                {stamp && (
                    <div aria-hidden className="pointer-events-none absolute inset-x-0 top-[40%] -rotate-[20deg] text-center text-[64pt] font-bold tracking-widest text-black/[0.08] uppercase">
                        {stamp}
                    </div>
                )}
                <table className="w-full border-collapse">
                    <thead className="table-header-group">
                        <tr>
                            <td className="pb-[8mm]">
                                <div className="flex items-start justify-between gap-6 border-b border-neutral-300 pb-[4mm]">
                                    <div className="grid gap-0.5">
                                        <span className="text-[13pt] font-semibold">{letterhead.legalName}</span>
                                        {letterhead.lines.map((line) => (
                                            <span key={line} className="text-[9pt] text-neutral-600">
                                                {line}
                                            </span>
                                        ))}
                                    </div>
                                    {letterhead.logo}
                                </div>
                            </td>
                        </tr>
                    </thead>
                    <tfoot className="table-footer-group">
                        <tr>
                            <td className="pt-[8mm]">
                                <div className="flex flex-wrap justify-between gap-x-6 gap-y-1 border-t border-neutral-300 pt-[3mm] text-[8.5pt] text-neutral-600">
                                    {footer.map((line) => (
                                        <span key={line}>{line}</span>
                                    ))}
                                </div>
                            </td>
                        </tr>
                    </tfoot>
                    <tbody>
                        <tr>
                            <td className="align-top">
                                <div className="mb-[6mm] flex flex-wrap items-end justify-between gap-6">
                                    <h1 className="text-[18pt] font-semibold">
                                        {title} <span className="font-mono text-[14pt]">{number}</span>
                                    </h1>
                                    {meta.length > 0 && (
                                        <dl className="grid grid-cols-[auto_auto] gap-x-4 gap-y-0.5 text-[9.5pt]">
                                            {meta.map((item) => (
                                                <div key={item.label} className="contents">
                                                    <dt className="text-neutral-600">{item.label}</dt>
                                                    <dd className="text-right tabular-nums">{item.value}</dd>
                                                </div>
                                            ))}
                                        </dl>
                                    )}
                                </div>
                                <div className="grid gap-[6mm]">{children}</div>
                            </td>
                        </tr>
                    </tbody>
                </table>
            </article>
        </div>
    );
}

import type { ReactNode } from 'react';
import { cn } from '@/lib/utils';

export type PrintColumn = { key: string; label: string; numeric?: boolean; width?: string };

export type PrintRow = { id: string; cells: Record<string, string> };

export type PrintTotal = { label: string; value: string; strong?: boolean };

export function PrintLines({ columns, rows }: { columns: PrintColumn[]; rows: PrintRow[] }) {
    return (
        <table className="w-full border-collapse text-[9.5pt]">
            <thead>
                <tr>
                    {columns.map((column) => (
                        <th key={column.key} scope="col" style={{ width: column.width }} className={cn('border-b border-black px-[1mm] py-[2mm] text-left font-semibold', column.numeric && 'text-right')}>
                            {column.label}
                        </th>
                    ))}
                </tr>
            </thead>
            <tbody>
                {rows.map((row) => (
                    <tr key={row.id} className="break-inside-avoid">
                        {columns.map((column) => (
                            <td key={column.key} className={cn('border-b border-neutral-300 px-[1mm] py-[2mm] align-top', column.numeric && 'text-right tabular-nums')}>
                                {row.cells[column.key]}
                            </td>
                        ))}
                    </tr>
                ))}
            </tbody>
        </table>
    );
}

export function PrintTotals({ totals }: { totals: PrintTotal[] }) {
    return (
        <dl className="ml-auto grid w-[70mm] break-inside-avoid grid-cols-[1fr_auto] gap-x-4 gap-y-1 text-[9.5pt]">
            {totals.map((total) => (
                <div key={total.label} className={cn('col-span-2 grid grid-cols-subgrid', total.strong && 'border-t border-black pt-[1.5mm] font-semibold')}>
                    <dt>{total.label}</dt>
                    <dd className="text-right tabular-nums">{total.value}</dd>
                </div>
            ))}
        </dl>
    );
}

export function PrintBlock({ title, children }: { title: string; children: ReactNode }) {
    return (
        <section className="break-inside-avoid">
            <h2 className="mb-[1.5mm] text-[8.5pt] font-semibold tracking-wide text-neutral-600 uppercase">{title}</h2>
            <div className="text-[9.5pt]">{children}</div>
        </section>
    );
}
